const respuesta = pm.response.json();

pm.test("La API responde 201 (usuario creado)", function () {
    pm.response.to.have.status(201);
});

pm.test("El nombre y el trabajo son los mismos que envié", function () {
    pm.expect(respuesta.name).to.eql(pm.environment.get("user_name"));
    pm.expect(respuesta.job).to.eql(pm.environment.get("user_job"));
});

pm.test("La respuesta trae el id y la fecha de creación", function () {
    pm.expect(respuesta.id).to.exist;
    pm.expect(respuesta.createdAt).to.exist;
});

// Guardo el id para usarlo en el siguiente caso de prueba
pm.environment.set("user_id", respuesta.id);
